WITH exploded AS (SELECT id, effective_from, currency, val FROM price_tiers LATERAL VIEW OUTER EXPLODE(discounts) t AS val), cleaned AS (SELECT *, CASE WHEN val >= 73 THEN 'High' WHEN val >= 37 THEN 'Medium' ELSE 'Low' END AS val_tier FROM exploded WHERE effective_from >= DATE '2024-08-27'), cleaned_price_tiers AS (SELECT id, effective_from, currency, val, ADD_MONTHS(effective_from, 6) AS effective_from_plus_months FROM cleaned WHERE currency = 'USD'), enriched AS (SELECT id, effective_from, currency, val, effective_from_plus_months, CUME_DIST() OVER (PARTITION BY currency ORDER BY val NULLS LAST) AS val_cume_dist, RANK() OVER (PARTITION BY currency ORDER BY val DESC NULLS LAST) AS val_rank, STDDEV_SAMP(val) OVER (PARTITION BY currency) AS currency_stddev_samp_val FROM cleaned_price_tiers), summary AS (SELECT currency, CASE WHEN currency_stddev_samp_val >= 62 THEN 'HIGH' ELSE 'LOW' END AS currency_stddev_samp_val_tier, CASE WHEN val >= 74 THEN 'PREMIUM' ELSE 'STANDARD' END AS val_tier, COUNT_IF(currency = 'THB') AS thb_events, SUM(CASE WHEN currency = 'THB' THEN val ELSE 0 END) AS thb_val, SUM(CASE WHEN currency = 'THB' THEN val ELSE 0 END) AS thb_val_2, COUNT(DISTINCT id) AS distinct_ids, PERCENTILE_APPROX(val, ARRAY(0.25, 0.5, 0.75)) AS val_quartiles, AVG(val_cume_dist) AS avg_val_cume_dist FROM enriched GROUP BY currency, CASE WHEN currency_stddev_samp_val >= 62 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN val >= 74 THEN 'PREMIUM' ELSE 'STANDARD' END) SELECT currency, currency_stddev_samp_val_tier, val_tier, thb_events, thb_val_2, avg_val_cume_dist, CASE WHEN currency RLIKE '^(EUR|THB)$' THEN 'EXTENDED' WHEN currency RLIKE '^(USD)$' THEN 'PRIORITY' ELSE 'CORE' END AS currency_zone FROM summary ORDER BY currency_stddev_samp_val_tier DESC NULLS LAST;
